python3 - <<'EOF'
import re
p='src/server_runner.ts'
s=open(p).read()

# 1. Per-session McpServer instead of one shared instance.
old_srv='''  const server = new McpServer({
    name: options.name,
    version: "1.0.0",
  }, {
    capabilities: {
      logging: {},
      tools: {
        listChanged: false
      }
    }
  });

  setupCb(server);

  const app = express();
  app.use(express.json());
'''
new_srv='''  // One McpServer per session. The SDK's Protocol.connect() replaces the
  // server's transport, so sharing a single McpServer across sessions routes
  // every response to whichever client connected last (GHSA-345p-7cg4-v4c7).
  const createServer = () => {
    const server = new McpServer({
      name: options.name,
      version: "1.0.0",
    }, {
      capabilities: {
        logging: {},
        tools: {
          listChanged: false
        }
      }
    });
    setupCb(server);
    return server;
  };

  // Full request/response bodies contain user data; only log them when asked.
  const logBodies = process.env.LOG_BODIES === "true";

  const app = express();
  app.use(express.json());

  // Liveness endpoint for the platform health check.
  app.get('/health', (_req, res) => {
    res.status(200).json({ status: 'ok', sessions: Object.keys(transports).length });
  });
'''
assert old_srv in s; s=s.replace(old_srv,new_srv)

# transports map must be declared before /health uses it -> move declaration up
decl='''  // Map to store transports by session ID
  const transports: { [sessionId: string]: StreamableHTTPServerTransport } = {};
'''
assert decl in s; s=s.replace(decl,'')
s=s.replace('''  const createServer = () => {''', decl.lstrip('\n')+'''
  const createServer = () => {''',1)

# body logging gated
s=s.replace('''    console.log(`Request received: ${req.method} ${req.url}`, {body: req.body});

    // Capture response data for logging
    const originalJson = res.json;
    res.json = function(body) {
      console.log(`Response being sent:`, JSON.stringify(body, null, 2));
      return originalJson.call(this, body);
    };
''','''    console.log(`Request received: ${req.method} ${req.url} method=${req.body?.method ?? 'batch'}`);
    if (logBodies) {
      console.log(`Request body:`, JSON.stringify(req.body));
      // Capture response data for logging
      const originalJson = res.json;
      res.json = function(body) {
        console.log(`Response being sent:`, JSON.stringify(body));
        return originalJson.call(this, body);
      };
    }
''')
s=s.replace('''      console.log(`Handling request for session: ${transport.sessionId}`);
      console.log(`Request body:`, JSON.stringify(req.body, null, 2));
''','''      console.log(`Handling request for session: ${transport.sessionId}`);
''')

# per-session connect + close
old_conn='''        // Clean up transport when closed
        transport.onclose = () => {
          const sid = transport.sessionId;
          if (sid && transports[sid]) {
            console.log(`Transport closed for session ${sid}, removing from transports map`);
            delete transports[sid];
          }
        };


        // Connect to the MCP server BEFORE handling the request
        console.log(`Connecting transport to MCP server...`);
        await server.connect(transport);'''
new_conn='''        const server = createServer();

        // Clean up transport and its server when closed
        transport.onclose = () => {
          const sid = transport.sessionId;
          if (sid && transports[sid]) {
            console.log(`Transport closed for session ${sid}, removing from transports map`);
            delete transports[sid];
          }
          server.close().catch(err => console.error(`Error closing server for session ${sid}:`, err));
        };


        // Connect to the MCP server BEFORE handling the request
        console.log(`Connecting transport to MCP server...`);
        await server.connect(transport);'''
assert old_conn in s; s=s.replace(old_conn,new_conn)

# graceful shutdown on SIGINT and SIGTERM (platforms send SIGTERM on redeploy)
old_sd_start="  process.on('SIGINT', async () => {\n    console.log('Shutting down server...');"
new_sd_start="  let shuttingDown = false;\n  const shutdown = async (signal: string) => {\n    if (shuttingDown) return;\n    shuttingDown = true;\n    console.log(`${signal} received, shutting down server...`);"
assert old_sd_start in s; s=s.replace(old_sd_start,new_sd_start)
old_sd_end='''    await express_server.close();
    await server.close();
    console.log('Server shutdown complete');
    process.exit(0);
  });
'''
new_sd_end='''    await new Promise<void>(resolve => express_server.close(() => resolve()));
    console.log('Server shutdown complete');
    process.exit(0);
  };
  process.on('SIGINT', () => { void shutdown('SIGINT'); });
  process.on('SIGTERM', () => { void shutdown('SIGTERM'); });
'''
assert old_sd_end in s; s=s.replace(old_sd_end,new_sd_end)
s=s.replace("  return {process, server, express_server}","  return {process, express_server}")
open(p,'w').write(s)
EOF
